  (* [comment removed for export] *)
  Lemma disjoint_fsW5_retire : forall slo shi' fp ff k O n,
    0 <= k ->
    disjoint_from (fs_W5 H slo shi' fp ff k) O n ->
    disjoint_from [(ff, ff + 8); (sh ff, sh ff + fshn k); (fp, fp + 1)]%Z O n.
  Proof.
    intros slo shi' fp ff k O n Hk D. unfold fs_W5 in D. cbn [disjoint_from fst snd] in *.
    pose proof (fsz_pos k Hk). destruct D as (D1 & D2 & D3 & D4 & D5 & _). repeat split; lia.
  Qed.

  (* [comment removed for export] *)
  Lemma AStateBlock_fs_call : forall LF k ff fp m0 m1 m2 LB b ioc implb S ds slo shi',
    as_RFS H LF m0 -> fresh_frame H LF k ff fp -> aceil <= slo ->
    AStateBlock LB m1 b ioc implb S ds -> fsobj H LF b SZ_SPCI_STATE ->
    (st_fb S <> FB_empty -> fsobj H LF (fb_begin (st_fb S)) (fb_cap (st_fb S))) ->
    munch (fs_W5 H slo shi' fp ff k) m1 m2 -> wmono bsegs m1 m2 -> AStateBlock LB m2 b ioc implb S ds.
  Proof.
    intros LF k ff fp m0 m1 m2 LB b ioc implb S ds slo shi' RF FF CEIL SB FO FOF MU WM.
    pose proof SB as (p & j7 & j16 & j4 & _ & RB & _ & _ & _ & _ & _ & _ & FB & _).
    pose proof (rblock_bounds _ _ RB) as (B1 & B2 & B3 & B4 & B5 & B6). pose proof RB as (_ & _ & _ & AP & _).
    eapply AStateBlock_transport; [exact SB| exact MU| exact WM| | | |].
    - eapply (fsobj_disjoint H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| exact AP| left; lia].
    - intros NE. destruct FB as (_ & OK & _). destruct OK as [E|(q & IN & RBq & _)]; [contradiction|].
      pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6). pose proof RBq as (_ & _ & _ & APq & _).
      eapply (fsobj_disjoint H HH); [exact RF| exact (FOF NE)| exact FF| exact C1| exact C2| exact C3| exact APq| left; lia].
    - eapply (fsobj_disjoint_sh H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| exact CEIL].
    - intros NE. destruct FB as (_ & OK & _). destruct OK as [E|(q & IN & RBq & _)]; [contradiction|].
      pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6).
      eapply (fsobj_disjoint_sh H HH); [exact RF| exact (FOF NE)| exact FF| exact C1| exact C2| exact C3| exact CEIL].
  Qed.

  (* [comment removed for export] *)
  Lemma AStateBlock_fs_retire : forall LF k ff fp m0 m1 m2 LB b ioc implb S ds,
    as_RFS H LF m0 -> fresh_frame H LF k ff fp ->
    AStateBlock LB m1 b ioc implb S ds -> fsobj H LF b SZ_SPCI_STATE ->
    (st_fb S <> FB_empty -> fsobj H LF (fb_begin (st_fb S)) (fb_cap (st_fb S))) ->
    munch [(ff, ff + 8); (sh ff, sh ff + fshn k); (fp, fp + 1)]%Z m1 m2 -> wmono bsegs m1 m2 -> AStateBlock LB m2 b ioc implb S ds.
  Proof.
    intros LF k ff fp m0 m1 m2 LB b ioc implb S ds RF FF SB FO FOF MU WM.
    pose proof (ff_facts H LF k ff fp FF) as (K0 & _). pose proof aceil_facts as (AF & _).
    pose proof SB as (p & j7 & j16 & j4 & _ & RB & _ & _ & _ & _ & _ & _ & FB & _).
    pose proof (rblock_bounds _ _ RB) as (B1 & B2 & B3 & B4 & B5 & B6). pose proof RB as (_ & _ & _ & AP & _).
    eapply AStateBlock_transport; [exact SB| exact MU| exact WM| | | |].
    - apply (disjoint_fsW5_retire aceil aceil); [lia|].
      eapply (fsobj_disjoint H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| exact AP| left; lia].
    - intros NE. destruct FB as (_ & OK & _). destruct OK as [E|(q & IN & RBq & _)]; [contradiction|].
      pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6). pose proof RBq as (_ & _ & _ & APq & _).
      apply (disjoint_fsW5_retire aceil aceil); [lia|].
      eapply (fsobj_disjoint H HH); [exact RF| exact (FOF NE)| exact FF| exact C1| exact C2| exact C3| exact APq| left; lia].
    - apply (disjoint_fsW5_retire aceil aceil); [lia|].
      eapply (fsobj_disjoint_sh H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| lia].
    - intros NE. destruct FB as (_ & OK & _). destruct OK as [E|(q & IN & RBq & _)]; [contradiction|].
      pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6).
      apply (disjoint_fsW5_retire aceil aceil); [lia|].
      eapply (fsobj_disjoint_sh H HH); [exact RF| exact (FOF NE)| exact FF| exact C1| exact C2| exact C3| lia].
  Qed.
